<?php if($order):$job=one('SELECT * FROM shop_jobs WHERE order_id=?',[$id]); ?><a class="back-link" href="/admin/bestellungen">← Alle Bestellungen</a><section class="panel form-panel"><div class="eyebrow"><?= e($order['reference']) ?></div><h2><?= e($order['product_name']) ?></h2><?php order_commerce_details($order,true); ?><dl class="detail-list"><div><dt>Kunde</dt><dd><?= e($order['email']) ?></dd></div><div><dt>Domain</dt><dd><?= e($order['domain']?:'–') ?></dd></div><div><dt>Preis / Zeitraum</dt><dd><?= money($order['amount_cents']) ?> / <?= cycle($order['billing']) ?></dd></div><div><dt>PayPal</dt><dd><?= e($order['paypal_mode'].' · '.$order['payment_status']) ?></dd></div><div><dt>PayPal-Referenz</dt><dd><?= e($order['payment_id']?:'Noch nicht erzeugt') ?></dd></div><div><dt>Bereitstellung</dt><dd><?= e($order['fulfillment_status']==='domain_verification'?'Wartet auf Bestätigung und Prüf-TXT des Kunden':$order['fulfillment_status']) ?></dd></div><?php if($job): ?><div><dt>Phase</dt><dd><?= e($job['phase'].' · '.$job['state']) ?></dd></div><?php endif ?></dl><?php if($dv=one('SELECT * FROM shop_hosting_domain_verifications WHERE order_id=?',[$id])): ?><div class="info-box"><?= icon('globe') ?><span><strong>Externe Domain: <?= e($dv['domain']) ?></strong><br>Bestätigung: <?= $dv['confirmed_ts']?date('d.m.Y H:i',(int)$dv['confirmed_ts']):'Noch nicht durch den Kunden erteilt' ?><br>Prüf-TXT: <?= $dv['verified_ts']?'Erfolgreich geprüft':'Noch nicht bestätigt' ?><?= $dv['activated_ts']?' · Domain eingerichtet':'' ?></span></div><?php endif ?><?php if(!empty($job['last_error'])): ?><div class="info-box"><?= icon('shield') ?><span><?= e($job['last_error']) ?></span></div><p class="muted">Vor einer Fortsetzung den Zustand beim Anbieter prüfen. Unklare Schreibvorgänge werden nicht automatisch wiederholt, damit keine doppelten Ressourcen oder Domainbestellungen entstehen.</p><?php endif ?><?php if($order['provider']==='manual' && ($job['state']??'')==='needs_action'): ?><div class="job-recovery"><h3>Persönliche Bereitstellung abschließen</h3><p>Bestätige erst, wenn die gekaufte Leistung bereitsteht. Sie erscheint anschließend als aktives Produkt im Kundenkonto.</p><form method="post" data-confirm="Die Leistung als fertig eingerichtet bestätigen?"><?= csrf() ?><input type="hidden" name="action" value="manual_fulfill"><input type="hidden" name="order_id" value="<?= $id ?>"><label class="field"><span>Leistungskennung / Projektname</span><input name="identifier" required maxlength="253" value="<?= e($order['domain']) ?>"></label><button class="button button-teal">Leistung bereitstellen <?= icon('check') ?></button></form></div><?php elseif(($job['state']??'')==='needs_action'): ?><div class="job-recovery"><?php if(in_array($job['phase'],['start','client_ready','website_ready','ftp_ready','clone_wait','clone_ready','configuring','configured','disk_resize_wait','checkout_ready','zone_wait'],true)): ?><form method="post"><?= csrf() ?><input type="hidden" name="action" value="job_retry"><input type="hidden" name="job_id" value="<?= $job['id'] ?>"><button class="button button-outline button-small">Einrichtung kontrolliert fortsetzen</button></form><?php endif ?><h3>Bereits eingerichtete Ressource übernehmen</h3><p class="small muted">Nach einem unklaren Schreibvorgang zuerst beim Anbieter prüfen. Lege die tatsächlich vorhandene Leistung unter Kunden & Produkte an und verbinde sie unter Ressourcen. Danach kannst du sie hier übernehmen, ohne erneut eine Bestellung oder Erstellung auszulösen.</p><form method="post" data-confirm="Die ausgewählte, bereits geprüfte Ressource als Ergebnis dieses bezahlten Auftrags übernehmen?"><?= csrf() ?><input type="hidden" name="action" value="job_resolve"><input type="hidden" name="job_id" value="<?= $job['id'] ?>"><label class="field"><span>Verbundenes Kundenprodukt</span><select name="service_id" required><option value="">Bitte auswählen</option><?php foreach(all('SELECT s.id,s.name,s.identifier FROM shop_services s JOIN shop_resource_links r ON r.service_id=s.id WHERE s.customer_id=? AND r.provider=?',[$order['customer_id'],$order['provider']]) as $candidate): ?><option value="<?= $candidate['id'] ?>"><?= e($candidate['name'].' · '.$candidate['identifier']) ?></option><?php endforeach ?></select></label><button class="button button-outline button-small">Vorhandene Ressource übernehmen</button></form></div><?php endif ?><?php admin_payment_form($order); ?><h3>Zahlungseingänge / Testbestätigungen</h3><?php $payments=all('SELECT p.*,a.source AS payment_source FROM shop_payments p LEFT JOIN shop_payment_attestations a ON a.payment_id=p.id WHERE p.order_id=? ORDER BY p.id DESC',[$id]);foreach($payments as $payment): ?><p><?= date_de($payment['received_at']) ?> · <?= money($payment['amount_cents']) ?> · <?= e($payment['transaction_id']) ?> · <?= e(['manual'=>'Manuell bestätigt','test'=>'Test ohne Geldfluss'][$payment['payment_source']]??'PayPal') ?></p><?php endforeach ?></section>
<?php else:$rows=all('SELECT o.*,c.email,j.state AS job_state,a.activated_ts,a.cancelled_ts,a.deleted_ts FROM shop_orders o JOIN customers c ON c.id=o.customer_id LEFT JOIN shop_jobs j ON j.order_id=o.id LEFT JOIN shop_order_admin a ON a.order_id=o.id WHERE '.($showDeleted?'COALESCE(a.deleted_ts,0)>0':'COALESCE(a.deleted_ts,0)=0').' ORDER BY o.id DESC'); ?><div class="button-row"><a class="button button-outline" href="/admin/bestellungen">Bestellungen</a><a class="button button-outline" href="/admin/bestellungen?ansicht=geloescht">Gelöschte Bestellungen</a></div><section class="panel"><?php if(!$rows):empty_state('lock','Noch keine Bestellungen','Nach Freischaltung deiner Tarife erscheinen hier PayPal-Bestellungen und Bereitstellungsaufträge.');else: ?><div class="table-scroll"><table><thead><tr><th>Bestellung / Kunde</th><th>Produkt</th><th>PayPal</th><th>Einrichtung</th><th></th></tr></thead><tbody><?php foreach($rows as $o): ?><tr><td><strong><?= e($o['reference']) ?></strong><small><?= e($o['email']) ?></small></td><td><?= e($o['product_name']) ?><small><?= money($o['amount_cents']) ?></small></td><td><?= e($o['payment_status']) ?><small><?= e($o['paypal_mode']) ?></small></td><td><?= e($o['fulfillment_status']==='domain_verification'?'Domainbestätigung erforderlich':$o['fulfillment_status']) ?></td><td><a class="text-link" href="/admin/bestellungen?id=<?= $o['id'] ?>">Prüfen & verwalten <?= icon('arrow') ?></a><?php if(!empty($o['activated_ts'])): ?><small>Manuell freigegeben</small><?php endif ?><?php if(!empty($o['cancelled_ts'])): ?><small>Durch Admin storniert</small><?php endif ?></td></tr><?php endforeach ?></tbody></table></div><?php endif ?></section><?php endif ?>
<?php endif ?>

